const contactCSS = ".opus-contact-form-card{background:#fff;border:1px solid #e7e5eb;border-radius:28px;padding:36px!important;box-shadow:0 14px 48px rgba(15,9,40,.07);scroll-margin-top:110px}\n.opus-contact-email{display:flex;align-items:center;justify-content:center;gap:12px;max-width:100%;padding:15px 18px;margin-top:24px;background:#f7f7f9;border:1px solid #eeecf1;border-radius:14px;color:#bd443c;text-align:left}\n.opus-contact-email small{display:block;font-size:12px;color:#686270}.opus-contact-email strong{display:block;font-size:15px;overflow-wrap:anywhere}.opus-contact-email:focus-visible{outline:2px solid #bd443c;outline-offset:4px}\n@media(max-width:600px){.opus-contact-form-card{margin-inline:16px!important;padding:24px 20px!important;border-radius:22px}.opus-contact-email{padding:13px 12px}.opus-contact-email strong{font-size:14px}}\n.opus-send-enquiry{display:flex;width:100%;align-items:center;justify-content:center;border:0;border-radius:999px;background:#e85d2a;color:#fff;padding:14px 24px;font-weight:600;cursor:pointer}.opus-send-enquiry:hover{background:#bd443c}.opus-send-enquiry:disabled{opacity:.65;cursor:wait}.opus-send-enquiry:focus-visible{outline:2px solid #bd443c;outline-offset:4px}.opus-enquiry-status:empty{display:none}.opus-enquiry-status{padding:12px 16px;border-radius:12px;background:#edf8f1;color:#195e35;font-size:14px;line-height:1.6}.opus-enquiry-status[data-error=true]{background:#fff1f0;color:#9b2525}\n";
const contactNavigationJS = "(() => {\n if(window.__opusContactNavigation)return;window.__opusContactNavigation=true;\n let landingPending=false;\n function land(){\n  if(!landingPending||location.pathname.replace(/\\/$/,'')!=='/contact')return;\n  const target=document.getElementById('enquiry-form');\n  if(!target||document.querySelector('.site-content')?.getAttribute('aria-busy')!=='false')return;\n  landingPending=false;setTimeout(()=>requestAnimationFrame(()=>{if(target.isConnected)target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}),180);\n }\n document.addEventListener('click',event=>{\n  if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;\n  const link=event.target instanceof Element?event.target.closest('a[href]'):null;if(!link||link.target==='_blank'||link.hasAttribute('download'))return;\n  let url;try{url=new URL(link.href)}catch{return}\n  if(url.origin!==location.origin||url.pathname.replace(/\\/$/,'')!=='/contact'||url.search)return;\n  if(url.hash&&url.hash!=='#enquiry-form')return;\n  landingPending=true;\n  if(location.pathname.replace(/\\/$/,'')==='/contact'){event.preventDefault();land();}\n },true);\n document.addEventListener('DOMContentLoaded',()=>{if(location.pathname.replace(/\\/$/,'')==='/contact'&&location.hash==='#enquiry-form')landingPending=true;land();});\n const observe=()=>new MutationObserver(land).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['aria-busy']});\n if(document.documentElement)observe();else document.addEventListener('DOMContentLoaded',observe,{once:true});\n})();\n";
